/*
** ============================================================================
** MACRO DEFINITIONS & DOCUMENTATION
** ============================================================================
** SIGINT: Signal interrupt, typically generated by Ctrl+C.
** SIGTERM: Termination signal, sent to request process termination.
*/

#include "ft_malcolm.h"

volatile sig_atomic_t g_running = 1;

/**
 * sigint_handler - Signal handler function for SIGINT/SIGTERM.
 * @signum: The signal number received (unused).
 * Side effects: Sets global flag g_running to 0 to signal termination.
 */
static void	sigint_handler(int signum)
{
	(void)signum;
	g_running = 0;
}

/**
 * init_signals - Configures signal handling for graceful shutdown.
 * Side effects: Registers sigint_handler for SIGINT and SIGTERM signals.
 */
void	init_signals(void)
{
	struct sigaction	sa;

	ft_bzero(&sa, sizeof(sa));
	sa.sa_handler = sigint_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	sigaction(SIGINT, &sa, NULL);
	sigaction(SIGTERM, &sa, NULL);
}
